INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7343814, 1147195, 12611, '<td valign="top">Beautifully seen.(and presented). should have been on the front page.</td>', 'Beautifully seen.(and presented). should have been on the front page.', '2015-04-20 10:07:33.000000', NULL, 0),
(7343815, 1147370, 12611, '<td valign="top">This shot shows vision and creativity- kudos.</td>', 'This shot shows vision and creativity- kudos.', '2015-04-20 10:08:06.000000', NULL, 0),
(7343816, 1147357, 12611, '<td valign="top">underratedly dreamy.</td>', 'underratedly dreamy.', '2015-04-20 10:09:13.000000', NULL, 0),
(7343817, 1147252, 12611, '<td valign="top">The bits of brown and decay make the shot excellent. so many times we strive for glossy perfection in architecture, or a main theme of decay, but the blend is oft times elusive, but here you have captured and subtly exploited it.</td>', 'The bits of brown and decay make the shot excellent. so many times we strive for glossy perfection in architecture, or a main theme of decay, but the blend is oft times elusive, but here you have captured and subtly exploited it.', '2015-04-20 10:10:57.000000', NULL, 0),
